% =========================================================================
% 車內生命徵象數位孿生系統：Phase 5 - MIMO 波束成形與 SCR 增強
% 針對 Phase 4 發現的「嬰兒 (CPD) 微弱訊號被雜訊淹沒」問題進行救援
% =========================================================================

clear; clc; close all;

% 1. 基本參數設定
fc = 60e9; c = 3e8; lambda = c/fc;
fps = 100; duration = 10; 
timeVec = (0:(duration*fps)-1) / fps;

% 2. 模擬嬰兒 (Baby/CPD) 的極微弱生命徵象
fr = 0.4; Ar = 0.0015; % 嬰兒呼吸：振幅僅 1.5mm
fh = 2.2; Ah = 0.0002; % 嬰兒心跳：振幅僅 0.2mm
displacement = Ar*sin(2*pi*fr*timeVec) + Ah*sin(2*pi*fh*timeVec);
clean_phase = (4 * pi * displacement) / lambda; % 理論上完美的純淨相位

% 3. 建立 4 天線均勻線性陣列 (Uniform Linear Array, ULA)
num_antennas = 4;
d = lambda / 2; % 天線間距為半波長
target_angle = 15; % 假設嬰兒坐在雷達偏右 15 度的副駕駛座/後座

% 計算引導向量 (Steering Vector)
theta = target_angle * pi / 180;
a = exp(-1i * 2 * pi * d / lambda * (0:num_antennas-1)' * sin(theta));

% 4. 數位孿生場景合成：注入極端車體震動與環境雜訊
% 產生多通道的嚴重背景雜訊矩陣 (每個天線收到的雜訊獨立)
noise_matrix = 0.8 * randn(num_antennas, length(timeVec)) + 1i * 0.8 * randn(num_antennas, length(timeVec));

% 各天線實際收到的訊號 = 目標訊號從特定角度抵達 + 嚴重雜訊
rx_signals = a * clean_phase + noise_matrix;

% 5. 比較 A：傳統單一天線 (Single Antenna) 的處理結果
% 擷取第一根天線的訊號 (這就是我們 Phase 4 失敗的原因)
single_ant_phase = real(rx_signals(1, :));
% 稍微用帶通濾波器搶救一下
single_filtered = bandpass(single_ant_phase, [0.15 2.5], fps);

% 6. 比較 B：導入 SCR 導引波束成形 (MIMO Beamforming)
% 將 4 根天線的訊號，對準 15 度角進行相位補償與同相疊加 (Maximum Ratio Combining)
w = a; % 取得目標方向的權重
bf_signal = (w') * rx_signals / num_antennas; % 空間濾波
bf_phase = real(bf_signal);
% 同樣用帶通濾波器處理
bf_filtered = bandpass(bf_phase, [0.15 2.5], fps);

% 7. 繪圖對比成果
figure('Position', [100, 100, 800, 500], 'Name', 'Beamforming Result'); %[output:0833d1f7]

% 單天線結果
subplot(2,1,1); %[output:0833d1f7]
plot(timeVec, single_filtered, 'Color', [0.5 0.5 0.5], 'LineWidth', 1); hold on; %[output:0833d1f7]
plot(timeVec, clean_phase, 'r', 'LineWidth', 1.5); %[output:0833d1f7]
title('Before Beamforming (Single Antenna) - Baby Signal Lost in Noise'); %[output:0833d1f7]
ylabel('Phase (rad)'); %[output:0833d1f7]
legend('Extracted Noisy Phase', 'Ground Truth (Clean Baby Signal)'); %[output:0833d1f7]
grid on; %[output:0833d1f7]

% 波束成形結果
subplot(2,1,2); %[output:0833d1f7]
plot(timeVec, bf_filtered, 'b', 'LineWidth', 1.5); hold on; %[output:0833d1f7]
plot(timeVec, clean_phase, 'r', 'LineWidth', 1.5); %[output:0833d1f7]
title('After Beamforming (4-Antenna MIMO) - Baby Signal Recovered!'); %[output:0833d1f7]
xlabel('Time (s)'); ylabel('Phase (rad)'); %[output:0833d1f7]
legend('Beamformed Phase', 'Ground Truth (Clean Baby Signal)'); %[output:0833d1f7]
grid on; %[output:0833d1f7]

disp('波束成形模擬完成！請查看對比圖。'); %[output:1935f46c]

